do $$ begin
 if (select count(*) from tcp)<>32 or (select count(*) from skp)<>34 then raise exception 'plan rows'; end if;
 if exists (select 1 from tcp join app.content_item_cells c on c.content_item_version_id=tcp.version_id and c.is_primary and c.superseded_by is null) then raise exception 'topic cell already present'; end if;
 if exists (select 1 from skp join app.content_item_cells c on c.content_item_version_id=skp.version_id and c.skill_code is not null and c.superseded_by is null) then raise exception 'skill cell already present'; end if;
end $$;
insert into app.content_item_cells (content_item_version_id,content_item_id,taxonomy_source_version,topic_code,skill_code,is_primary,assignment_status,source,model_run_id,validated_by,validated_at,validation_decision_id)
select version_id,item_id,tsv,topic,null,true,'validated','variant_topic_fill_2026_10_03:'||src,case src when 'three_family' then 'variant-topic-fill-2026-10-03 (gemini-3.8-flash + deepseek-v4-pro + gpt-6.1-sol, 2 samples each; >=5 of 6, or >=4 of 6 agreeing with the seed-pooled plurality)' else 'variant-topic-fill-2026-10-03 (topic inherited from the seed)' end,null,now(),gen_random_uuid() from tcp;
create temporary table ins on commit drop as select skp.*, gen_random_uuid() vd from skp join app.taxonomy_cells tc on tc.taxonomy_source_version=skp.tsv and tc.topic_code=skp.topic and tc.skill_code=skp.skill;
insert into app.content_item_cells (content_item_version_id,content_item_id,taxonomy_source_version,topic_code,skill_code,is_primary,assignment_status,source,model_run_id,validated_by,validated_at,validation_decision_id)
select version_id,item_id,tsv,topic,skill,false,status,'skill_variant_fill_4voter_2026_10_03:'||tier,'skills-variant-fill-2026-10-03 (4 voters: claude-opus-5, gpt-5.5, gemini-2.5-pro, gemini-3.8-flash; validated at >=3 of 4)',null,case when status='validated' then now() end,case when status='validated' then vd end from ins;
